  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I initiate a custom furniture commission with WRYDECO?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You can initiate a custom commission by emailing support@wrydeco.com with your room dimensions, desired furniture category, sketches, or reference links. Our design team will review your specifications, provide complimentary guidance, and send a detailed quotation with bespoke options."
      }
    },
    {
      "@type": "Question",
      "name": "Can I modify the dimensions of standard WRYDECO catalog pieces?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Many WRYDECO catalog designs—including organic curved bookshelves, floating branch ledges, and platform beds—can be tailored in width, height, platform depth, and wood finish to suit your exact room requirements."
      }
    },
    {
      "@type": "Question",
      "name": "How long does the custom crafting and delivery process take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Estimated processing and crafting takes approximately 15 to 20 business days, followed by an estimated 3 to 5 business days in transit after dispatch, for a total estimated delivery window of 18 to 25 business days. Timelines are estimates rather than guaranteed delivery dates."
      }
    },
    {
      "@type": "Question",
      "name": "What is the cancellation policy on bespoke custom orders?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "WRYDECO provides a 6-hour Golden Window immediately after ordering during which you can cancel your order for a 100% free refund or change size, finish, and shipping details by contacting support@wrydeco.com. Once the 6-hour window closes, production begins and orders cannot be canceled."
      }
    }
  ]
}
